## ✅ Full C Program with All Matrix Operations

```c
#include <stdio.h>

#define SIZE 10

void inputMatrix(int mat[SIZE][SIZE], int row, int col) {
    printf("Enter elements (%dx%d):\n", row, col);
    for (int i = 0; i < row; i++)
        for (int j = 0; j < col; j++)
            scanf("%d", &mat[i][j]);
}

void printMatrix(int mat[SIZE][SIZE], int row, int col) {
    for (int i = 0; i < row; i++) {
        for (int j = 0; j < col; j++)
            printf("%d ", mat[i][j]);
        printf("\n");
    }
}

void addMatrix(int a[SIZE][SIZE], int b[SIZE][SIZE], int row, int col) {
    printf("\nMatrix Addition:\n");
    for (int i = 0; i < row; i++) {
        for (int j = 0; j < col; j++)
            printf("%d ", a[i][j] + b[i][j]);
        printf("\n");
    }
}

void subtractMatrix(int a[SIZE][SIZE], int b[SIZE][SIZE], int row, int col) {
    printf("\nMatrix Subtraction:\n");
    for (int i = 0; i < row; i++) {
        for (int j = 0; j < col; j++)
            printf("%d ", a[i][j] - b[i][j]);
        printf("\n");
    }
}

void multiplyMatrix(int a[SIZE][SIZE], int b[SIZE][SIZE], int r1, int c1, int c2) {
    int result[SIZE][SIZE] = {0};

    printf("\nMatrix Multiplication:\n");
    for (int i = 0; i < r1; i++)
        for (int j = 0; j < c2; j++)
            for (int k = 0; k < c1; k++)
                result[i][j] += a[i][k] * b[k][j];

    printMatrix(result, r1, c2);
}

void sumDiagonal(int mat[SIZE][SIZE], int n) {
    int sum = 0;
    for (int i = 0; i < n; i++)
        sum += mat[i][i];

    printf("\nSum of Principal Diagonal = %d\n", sum);
}

void transpose(int mat[SIZE][SIZE], int row, int col) {
    printf("\nTranspose:\n");
    for (int i = 0; i < col; i++) {
        for (int j = 0; j < row; j++)
            printf("%d ", mat[j][i]);
        printf("\n");
    }
}

void rowWithMaxSum(int mat[SIZE][SIZE], int row, int col) {
    int maxSum = -1, rowIndex = -1;

    for (int i = 0; i < row; i++) {
        int sum = 0;
        for (int j = 0; j < col; j++)
            sum += mat[i][j];

        if (sum > maxSum) {
            maxSum = sum;
            rowIndex = i;
        }
    }

    printf("\nRow %d has maximum sum = %d\n", rowIndex + 1, maxSum);
}

int main() {
    int a[SIZE][SIZE], b[SIZE][SIZE];
    int row, col;

    printf("Enter number of rows and columns: ");
    scanf("%d%d", &row, &col);

    printf("\nMatrix A:\n");
    inputMatrix(a, row, col);

    printf("\nMatrix B:\n");
    inputMatrix(b, row, col);

    printf("\nMatrix A:\n");
    printMatrix(a, row, col);

    printf("\nMatrix B:\n");
    printMatrix(b, row, col);

    addMatrix(a, b, row, col);
    subtractMatrix(a, b, row, col);

    // For multiplication, col of A == row of B, assuming square matrix here
    multiplyMatrix(a, b, row, col, col);

    if (row == col)
        sumDiagonal(a, row);
    else
        printf("\nPrincipal diagonal sum not possible for non-square matrix.\n");

    transpose(a, row, col);
    rowWithMaxSum(a, row, col);

    return 0;
}
```

