}

void printMatrix(int mat[SIZE][SIZE], int row, int col) {
    for (int i = 0; i < row; i++) {
        for (int j = 0; j < col; j++)
            printf("%d ", mat[i][j]);
        printf("\n");
    }
}

void addMatrix(int a[SIZE][SIZE], int b[SIZE][SIZE], int res[SIZE][SIZE], int row, int col) {
    for (int i = 0; i < row; i++)
        for (int j = 0; j < col; j++)
            res[i][j] = a[i][j] + b[i][j];
}

void subtractMatrix(int a[SIZE][SIZE], int b[SIZE][SIZE], int res[SIZE][SIZE], int row, int col) {
    for (int i = 0; i < row; i++)
        for (int j = 0; j < col; j++)
            res[i][j] = a[i][j] - b[i][j];
}

void multiplyMatrix(int a[SIZE][SIZE], int b[SIZE][SIZE], int res[SIZE][SIZE], int r1, int c1, int c2) {
    for (int i = 0; i < r1; i++)
        for (int j = 0; j < c2; j++) {
            res[i][j] = 0;
            for (int k = 0; k < c1; k++)
                res[i][j] += a[i][k] * b[k][j];
        }
}

int sumDiagonal(int mat[SIZE][SIZE], int n) {
    int sum = 0;
    for (int i = 0; i < n; i++)
        sum += mat[i][i];
    return sum;
}

void transpose(int mat[SIZE][SIZE], int res[SIZE][SIZE], int row, int col) {
    for (int i = 0; i < row; i++)
        for (int j = 0; j < col; j++)
            res[j][i] = mat[i][j];
}

int rowWithMaxSum(int mat[SIZE][SIZE], int row, int col) {
    int maxSum = -1, rowIndex = -1;

    for (int i = 0; i < row; i++) {
        int sum = 0;
        for (int j = 0; j < col; j++)
            sum += mat[i][j];

        if (sum > maxSum) {
            maxSum = sum;
            rowIndex = i;
        }
    }
    return rowIndex;
}

int main() {
