    int addRes[SIZE][SIZE], subRes[SIZE][SIZE], mulRes[SIZE][SIZE], transRes[SIZE][SIZE];
    int row, col;

    printf("Enter number of rows and columns: ");
    scanf("%d%d", &row, &col);

    printf("\nMatrix A:\n");
    inputMatrix(a, row, col);

    printf("\nMatrix B:\n");
    inputMatrix(b, row, col);

    // ADDITION
    addMatrix(a, b, addRes, row, col);
    printf("\nAddition Result:\n");
    printMatrix(addRes, row, col);

    // SUBTRACTION
    subtractMatrix(a, b, subRes, row, col);
    printf("\nSubtraction Result:\n");
    printMatrix(subRes, row, col);

    // MULTIPLICATION (Assuming square matrices or compatible size)
    multiplyMatrix(a, b, mulRes, row, col, col);
    printf("\nMultiplication Result:\n");
    printMatrix(mulRes, row, col);

    // SUM OF PRINCIPAL DIAGONAL (only for square matrices)
    if (row == col) {
        int diagSum = sumDiagonal(a, row);
        printf("\nSum of Principal Diagonal of A = %d\n", diagSum);
    } else {
        printf("\nDiagonal sum not applicable to non-square matrices.\n");
    }

    // TRANSPOSE
    transpose(a, transRes, row, col);
    printf("\nTranspose of Matrix A:\n");
    printMatrix(transRes, col, row);  // Note the row and col are swapped here

    // ROW WITH MAXIMUM SUM
    int rowIndex = rowWithMaxSum(a, row, col);
    printf("\nRow %d of Matrix A has maximum sum.\n", rowIndex + 1);

    return 0;
}
